// PreToolUse hook: deny Edit/Write on generated or tool-managed files.
import { readFileSync } from "node:fs"

const input = JSON.parse(readFileSync(0, "utf8"))
const filePath = String(input.tool_input?.file_path ?? "").replace(/\\/g, "/")

const rules = [
  [
    /(^|\/)docs\/\.source\//,
    "docs/.source/ is auto-generated by Fumadocs — run `pnpm docs:dev` or `pnpm docs:build` to regenerate it instead of editing.",
  ],
  [
    /(^|\/)scripts\/i18n-baseline\.json$/,
    "scripts/i18n-baseline.json is generated — run `pnpm lint:i18n:baseline` after intentional i18n changes instead of editing.",
  ],
  [
    /(^|\/)pnpm-lock\.yaml$/,
    "pnpm-lock.yaml is managed by pnpm — run `pnpm install` / `pnpm update` from the repo root instead of editing.",
  ],
]

const hit = rules.find(([pattern]) => pattern.test(filePath))
if (!hit) process.exit(0)

console.log(
  JSON.stringify({
    hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: "deny",
      permissionDecisionReason: hit[1],
    },
  })
)
